head.script:
scwin.expTotal = function(row) {
    //debugger;
    var arr = dcList.getRowData(row).slice(dcList.getColumnIndex('target') + 1, dcList.getRowData(row).length - 1);
    var data = arr.reduce(function(a, b) {
        return Number(a) + Number(b)
    }, 0);
    return data;
};
scwin.gvGridList1_onviewchange = function(info) {
    //gvGridList1.refreshCell( info.rowIndex , "total" );
};
scwin.trigger1_onclick = function(e) {
    console.log("delete");
    dcList.deleteRow(1);
};
scwin.trigger2_onclick = function(e) {
    console.log("modify");
    dcList.modifyRowStatus(1, 'D');
    //dcList.modifyMatchedStatus( "chk" , "1" , "D" );
};
scwin.trigger4_onclick = function(e) {
    //debugger;
    dcList.modifyMatchedStatus("chk", "1", "D");
};
scwin.trigger5_onclick = function(e) {
    dcList.modifyRangeStatus(1, 2, 'D');
};
scwin.textbox1_onclick = function(e) {
    dcList.deleteRow(1);
};
scwin.textbox3_onclick = function(e) {
    dcList.modifyRowStatus(1, 'R');
};
scwin.textbox5_onclick = function(e) {
    gvGridList1.setCellChecked(1, 'chk', true);
    dcList.modifyMatchedStatus("chk", "1", "D");
};
scwin.textbox6_onclick = function(e) {
    dcList.modifyRangeStatus(1, 1, 'D');
};
scwin.textbox7_onclick = function(e) {
    gvGridList1.setCellChecked(1, 'chk', true);
    gvGridList1.modifyCheckedStatus("chk", "D");
};
scwin.__checksubTotal = function(v1, v2, v3, v4, v5, v6) {
    var column20 = WebSquare.wUnit.getJq("#gvGridList1_body_tbody tr:nth-child(5)").find("td#column20").text() == v1;
    var column13 = WebSquare.wUnit.getJq("#gvGridList1_body_tbody tr:nth-child(5)").find("td#column13").text() == v2;
    var column12 = WebSquare.wUnit.getJq("#gvGridList1_body_tbody tr:nth-child(5)").find("td#column12").text() == v3;
    var column11 = WebSquare.wUnit.getJq("#gvGridList1_body_tbody tr:nth-child(5)").find("td#column11").text() == v4;
    var column28 = WebSquare.wUnit.getJq("#gvGridList1_body_tbody tr:nth-child(5)").find("td#column28").text() == v5;
    var column24 = WebSquare.wUnit.getJq("#gvGridList1_body_tbody tr:nth-child(5)").find("td#column24").text() == v6;
    return column20 && column13 && column12 && column11 && column28 && column24;
}
scwin.__checkfooter = function(v1, v2, v3, v4, v5, v6) {
    var val1 = WebSquare.wUnit.getJq("#gvGridList1_column21").text() == v1;
    var val2 = WebSquare.wUnit.getJq("#gvGridList1_column17").text() == v2;
    var val3 = WebSquare.wUnit.getJq("#gvGridList1_column16").text() == v3;
    var val4 = WebSquare.wUnit.getJq("#gvGridList1_column15").text() == v4;
    var val5 = WebSquare.wUnit.getJq("#gvGridList1_column29").text() == v5;
    var val6 = WebSquare.wUnit.getJq("#gvGridList1_column25").text() == v6;
    return val1 && val2 && val3 && val4 && val5 && val6;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();

    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('textbox1').click()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.__checksubTotal('subTotal', '1', '1', '1', '1', '1')", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.__checkfooter('footer', '8', '2.6666666666666665', '1', '4', '3')", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('textbox2').click()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.__checksubTotal('subTotal', '1', '1', '1', '1', '1')", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.__checkfooter('footer', '8', '2.6666666666666665', '1', '4', '3')", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('textbox3').click()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.__checksubTotal('subTotal', '3', '1.5', '1', '2', '2')", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.__checkfooter('footer', '10', '2.5', '1', '4', '4')", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('textbox5').click()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.__checksubTotal('subTotal', '1', '1', '1', '1', '1')", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.__checkfooter('footer', '8', '2.6666666666666665', '1', '4', '3')", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('textbox6').click()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.__checksubTotal('subTotal', '1', '1', '1', '1', '1')", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.__checkfooter('footer', '8', '2.6666666666666665', '1', '4', '3')", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('textbox7').click()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.__checksubTotal('subTotal', '1', '1', '1', '1', '1')", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.__checkfooter('footer', '8', '2.6666666666666665', '1', '4', '3')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

